<script setup>
import { ref, computed } from 'vue'
const props = defineProps({ snapshot: Object, manual: Boolean, compact: Boolean })
const emit = defineEmits(['select-path','execute'])
const filter = ref('all')
const rows = computed(() => (props.snapshot?.recent_tasks || []).filter(r => filter.value === 'all' || (filter.value === 'done' ? r.accepted && r.completed : filter.value === 'late' ? r.accepted && !r.completed : !r.accepted)))
const fmt = v => v == null ? '—' : Number(v).toFixed(3)
const nodeName = n => props.snapshot.nodes.find(v=>v.id===n)?.kind==='cloud' ? 'C0' : 'E'+n
const path = r => r.path?.map(nodeName).join(' → ') || '—'
function selectCandidate(r) { emit('select-path', { ...r, source: props.snapshot.current_task.source, access_edge: props.snapshot.current_task.access_edge }) }
</script>
<template><div v-if="compact" class="compact-task-table"><el-table :data="[...rows].reverse()" height="100%" size="small" highlight-current-row @row-click="row=>emit('select-path',row)" empty-text="尚未调度任务，请加载任务后开始推演"><el-table-column label="任务 ID" width="82"><template #default="{row}">T-{{ row.task_index }}</template></el-table-column><el-table-column prop="kind_name" label="任务类型" width="88"/><el-table-column label="源终端" width="70"><template #default="{row}">U{{ row.source }}</template></el-table-column><el-table-column label="执行节点" width="80"><template #default="{row}">{{ row.accepted?nodeName(row.destination):'—' }}</template></el-table-column><el-table-column prop="resource_name" label="计算资源" width="80"/><el-table-column label="传输路径" min-width="130"><template #default="{row}">{{ path(row) }}</template></el-table-column><el-table-column label="完成时延" width="88"><template #default="{row}">{{ row.accepted?fmt(row.delay)+' s':'—' }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><span :class="['task-state',row.accepted?(row.completed?'completed':'late'):'rejected']">{{ row.accepted?(row.completed?'按期完成':'超时'):'已拒绝' }}</span></template></el-table-column></el-table></div><div v-else><div class="panel-heading"><div><div class="eyebrow">TASK DISPATCH</div><h3>任务与候选动作</h3></div><span class="muted">选择动作或任务以高亮路径</span></div><template v-if="snapshot?.current_task"><div class="task-summary"><strong>#{{ snapshot.current_task.task_index }} · {{ snapshot.current_task.kind_name }}</strong><span>时隙 {{ snapshot.current_task.slot }}</span><span>U{{ snapshot.current_task.source }} → E{{ snapshot.current_task.access_edge }}</span><span>输入 / 输出 {{ fmt(snapshot.current_task.data_mb) }} / {{ fmt(snapshot.current_task.output_mb) }} MB</span><span>{{ fmt(snapshot.current_task.compute_gflop) }} GFLOP</span><span>时限 {{ fmt(snapshot.current_task.deadline_s) }} s</span><span>优先级 {{ snapshot.current_task.priority }}</span><span>{{ snapshot.current_task.feasible_action_count }} 个可行动作</span></div><el-table :data="snapshot.current_task.candidates" max-height="230" size="small" highlight-current-row @row-click="selectCandidate"><el-table-column prop="action_id" label="动作" width="65"/><el-table-column prop="destination_label" label="执行节点" width="105"/><el-table-column prop="resource_name" label="芯片" width="75"/><el-table-column label="多跳路径" min-width="150"><template #default="{row}">{{ path(row) }}</template></el-table-column><el-table-column label="算力 f"><template #default="{row}">{{ fmt(row.compute_share) }}</template></el-table-column><el-table-column label="功率 p"><template #default="{row}">{{ fmt(row.uplink_power) }}</template></el-table-column><el-table-column label="预估时延 / 能耗" min-width="130"><template #default="{row}">{{ fmt(row.estimated_delay) }} / {{ fmt(row.estimated_energy) }}</template></el-table-column><el-table-column v-if="manual" label="操作" width="85"><template #default="{row}"><el-button link type="primary" @click.stop="emit('execute',row.action_id)">执行</el-button></template></el-table-column></el-table></template><p v-else class="muted">当前没有待调度任务</p><div class="table-subhead"><h4>已调度任务流</h4><el-select v-model="filter" size="small" style="width:150px"><el-option label="全部状态" value="all"/><el-option label="按期完成" value="done"/><el-option label="超时未完成" value="late"/><el-option label="拒绝" value="rejected"/></el-select></div><el-table :data="rows" max-height="300" size="small" highlight-current-row @row-click="row => emit('select-path',row)"><el-table-column prop="task_index" label="任务" width="65"/><el-table-column prop="slot" label="时隙" width="60"/><el-table-column prop="kind_name" label="类型" width="100"/><el-table-column label="状态" width="100"><template #default="{row}"><span :class="row.accepted ? row.completed ? 'good' : 'warn' : 'bad'">{{ row.accepted ? row.completed ? '按期完成' : '超时' : '拒绝' }}</span></template></el-table-column><el-table-column label="路径" min-width="130"><template #default="{row}">{{ path(row) }}</template></el-table-column><el-table-column prop="resource_name" label="芯片" width="70"/><el-table-column label="f / p" min-width="110"><template #default="{row}">{{ fmt(row.compute_share) }} / {{ fmt(row.uplink_power) }}</template></el-table-column><el-table-column label="时延 / 能耗" min-width="115"><template #default="{row}">{{ fmt(row.delay) }} / {{ fmt(row.energy) }}</template></el-table-column><el-table-column label="奖励" width="80"><template #default="{row}">{{ fmt(row.reward) }}</template></el-table-column></el-table></div></template>
